effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _SourceTex_TexelSize (1.0 / vec2(textureSize(inputImg, 0)))
vec4 u_xlat0;
vec4 u_xlat1;
float u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec4 u_xlat6;
vec4 u_xlat7;
vec2 u_xlat9;
float u_xlat10;
float u_xlat18;
bool u_xlatb18;
float u_xlat20;
bool u_xlatb20;
float u_xlat25;
float u_xlat26;
float u_xlat28;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.x = _radius + _radius;
    u_xlat1.x = roundEven(u_xlat1.x);
    u_xlat9.xy = vec2(_radius, _threshold) * vec2(_radius, _threshold);
    u_xlat9.xy = vec2(0.5, 0.5) / u_xlat9.xy;
    u_xlat25 = u_xlat9.x * 0.318309873;
    u_xlat2 = 0.398942292 / _threshold;
    u_xlat3.x = float(0.0);
    u_xlat3.y = float(0.0);
    u_xlat3.z = float(0.0);
    u_xlat3.w = float(0.0);
    u_xlat10 = 0.0;
    u_xlat4.x = (-u_xlat1.x);
    while(true){
        u_xlatb18 = u_xlat1.x<u_xlat4.x;
        if(u_xlatb18){break;}
        u_xlat18 = u_xlat4.x * u_xlat4.x;
        u_xlat18 = u_xlat1.x * u_xlat1.x + (-u_xlat18);
        u_xlat18 = sqrt(u_xlat18);
        u_xlat5 = u_xlat3;
        u_xlat26 = u_xlat10;
        u_xlat4.y = (-u_xlat18);
        while(true){
            u_xlatb20 = u_xlat18<u_xlat4.y;
            if(u_xlatb20){break;}
            u_xlat20 = dot(u_xlat4.xy, u_xlat4.xy);
            u_xlat20 = u_xlat9.x * (-u_xlat20);
            u_xlat20 = u_xlat20 * 1.44269502;
            u_xlat20 = exp2(u_xlat20);
            u_xlat20 = u_xlat25 * u_xlat20;
            u_xlat6.xy = u_xlat4.xy * _SourceTex_TexelSize.xy + acScreenNorm.xy;
            u_xlat6 = texture(inputImg, u_xlat6.xy);
            u_xlat7 = (-u_xlat0) + u_xlat6;
            u_xlat28 = dot(u_xlat7, u_xlat7);
            u_xlat28 = u_xlat9.y * (-u_xlat28);
            u_xlat28 = u_xlat28 * 1.44269502;
            u_xlat28 = exp2(u_xlat28);
            u_xlat28 = u_xlat2 * u_xlat28;
            u_xlat7.x = u_xlat20 * u_xlat28;
            u_xlat26 = u_xlat28 * u_xlat20 + u_xlat26;
            u_xlat5 = u_xlat7.xxxx * u_xlat6 + u_xlat5;
            u_xlat4.y = u_xlat4.y + 1.0;
        }
        u_xlat3 = u_xlat5;
        u_xlat10 = u_xlat26;
        u_xlat4.x = u_xlat4.x + 1.0;
    }
    u_xlat1 = u_xlat3 / vec4(u_xlat10);
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2 = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2 : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
